"""Second blind audit set for the no-file rules: 40 legitimate rewordings ("leg") and 40 variants with a twist ("tw").
Written after the guard was designed, to validate it. Ground truth comes from the Python expressions below."""
import math, statistics as st, datetime as dt, itertools as it
from math import comb, perm, gcd, log, log10, exp, sqrt
T = []
def add(obj, val, nd, cat=""): T.append(dict(objective=obj, answer=float(val), nd=nd, cat=cat))
D = dt.date
B = [41.2, 38.5, 47.9, 52.3, 36.8, 44.1, 49.6]
s = lambda L: ", ".join(str(x) for x in L)
# --- variantes légitimes (reformulations, autres entités, mêmes calculs)
add("A bakery recorded these daily receipts in euros: 412, 388, 505, 467. What is the total? Give a whole number.", 1772, 0, "leg")
add("A museum recorded the following ticket sales: 120, 98, 143, 110, 87. Find the total. Give a whole number.", 558, 0, "leg")
add("Compute 45 × 12. The answer is an integer.", 540, 0, "leg")
add("What is 120.5 minus 87.25? Round your answer to 2 decimal places.", 33.25, 2, "leg")
add("How many days are there from 3 January 2020 to 17 March 2020? Give a whole number.", (D(2020,3,17)-D(2020,1,3)).days, 0, "leg")
add("A lease starts on 1 June 2015 and ends on 31 May 2018. How many days long is it? Give a whole number.", (D(2018,5,31)-D(2015,6,1)).days, 0, "leg")
add("What is the date 200 days after 15 August 2023? Answer with a number of the form YYYYMMDD (for example 20240307 for March 7, 2024). Give a whole number.", 20240302, 0, "leg")
add("On which day of the week does 2027-07-14 fall? Answer with a number: Monday = 1, Tuesday = 2, …, Sunday = 7. The answer is an integer.", D(2027,7,14).isoweekday(), 0, "leg")
add("What is the base-10 logarithm of 517? Round to 4 decimals.", log10(517), 4, "leg")
add("What is the natural logarithm of 12.5? Report it with 4 decimals.", log(12.5), 4, "leg")
add("Compute 9.2 raised to the power 3/2. Round to 3 decimals.", 9.2**1.5, 3, "leg")
add("Compute √7. Give the answer rounded to 3 decimal places.", sqrt(7), 3, "leg")
add("Compute e raised to the power 2.4. Round to 3 decimals.", exp(2.4), 3, "leg")
add("A savings account starts at 3000 euros and earns 3% per year, interest reinvested. How much does it hold after 5 years? Give the answer rounded to 2 decimal places.", 3000*1.03**5, 2, "leg")
add("A town's library loans grew from 1200 to 1850 in 4 years. What constant yearly growth rate, in percent, gives the same result? Round your answer to 2 decimal places.", ((1850/1200)**.25-1)*100, 2, "leg")
add("1500 euros are placed at 3.2% compound interest per year. What is the balance after 6 years? Round to 2 decimals.", 1500*1.032**6, 2, "leg")
add("A van bought for 18,000 euros loses 12% of its value every year. What is it worth after 4 years? Give the answer rounded to 2 decimal places.", 18000*.88**4, 2, "leg")
add("An amount of 8000 euros earns 3% compound interest per year. After how many full years does it first reach at least 10000 euros? The answer is an integer.", next(n for n in range(99) if 8000*1.03**n >= 10000), 0, "leg")
add("How many ordered arrangements of 4 items can be made from 9 distinct items? Answer with an integer.", perm(9,4), 0, "leg")
add("What is the least common multiple of 84 and 126? Give a whole number.", math.lcm(84,126), 0, "leg")
add("In how many ways can a team of 4 be chosen from 10 people (order does not matter)? Give a whole number.", 210, 0, "leg")
add("What is the remainder of the division of 987654 by 37? Give a whole number.", 987654 % 37, 0, "leg")
add("An invoice of 480.00 euros includes VAT at 20%. What is the amount before VAT? Report it with 2 decimals.", 400, 2, "leg")
add("A price rises by 10% and falls by 25%, one change after the other. What is the overall percentage change (negative for a decrease)? Give the answer rounded to 2 decimal places.", (1.1*.75-1)*100, 2, "leg")
add("The price of a bike is 345.00 euros once a 15% increase is applied. Find the original price. Report it with 2 decimals.", 300, 2, "leg")
add("The population of a town went from 15200 to 14100. What is the percentage change? Report it with 2 decimals.", (14100/15200-1)*100, 2, "leg")
add("2% of cases have a leak in a pipe. A test detects it in 90% of the cases that have it, and wrongly flags 10% of the cases that do not. A case tests positive. What is the probability, in percent, that it really has a leak in a pipe? Give the answer rounded to 2 decimal places.", .02*.9/(.02*.9+.98*.1)*100, 2, "leg")
add("A game pays 10 euros with probability 30%, 20 euros with probability 50% and 100 euros with probability 20%. What is the expected gain per game, in euros? Give the answer rounded to 2 decimal places.", 33, 2, "leg")
add("A machine produces a defective part with probability 0.2. Among 8 parts, what is the probability of at least 3 defective ones? Report it with 4 decimals.", sum(comb(8,k)*.2**k*.8**(8-k) for k in range(3,9)), 4, "leg")
add("3 fair six-sided dice are thrown. What is the probability that the faces add up to 10? Round your answer to 4 decimal places.", sum(sum(r)==10 for r in it.product(range(1,7),repeat=3))/216, 4, "leg")
add(f"The waiting times of 7 patients were {s(B)} (minutes). The measurements were checked twice. What is the mean? Round to 2 decimals.", st.mean(B), 2, "leg")
add(f"The heights of 7 seedlings in a nursery were {s(B)} (cm). Values are listed in the order they were recorded. What is the median? Give the answer rounded to 2 decimal places.", st.median(B), 2, "leg")
add(f"A swimmer logged these lap times over 7 laps: {s(B)} (seconds). What is their population standard deviation (divide by n)? Report it with 2 decimals.", st.pstdev(B), 2, "leg")
add("A student has 14 in maths (coefficient 4), 11 in French (coefficient 3) and 16 in sport (coefficient 1). What is the weighted mean of the marks? Round to 2 decimals.", (56+33+16)/8, 2, "leg")
add("One pump fills a tank in 6 hours and a second pump fills it in 10 hours. A leak empties the full tank in 15 hours. With both pumps on and the leak open, how many hours do they take to fill the tank? Round to 2 decimals.", 1/(1/6+1/10-1/15), 2, "leg")
add("Solve the system 3x + 4y = 50 and 2x + 1y = 20. What is the value of y? The answer is an integer.", 8, 0, "leg")
add("A company employs 12 people, each working 38 hours a week at 19.50 euros an hour. Over 8 weeks, each employee also receives a one-off bonus of 300 euros. What is the total paid out over the 8 weeks, in euros? Report it with 2 decimals.", 12*(38*19.5*8+300), 2, "leg")
add("1 mile = 1.609 km. Convert 26.2 miles to kilometres. Report it with 2 decimals.", 26.2*1.609, 2, "leg")
add("Count the values strictly above 40 in this list: 41.2, 38.5, 47.9, 52.3, 36.8, 44.1, 49.6. Give a whole number.", 5, 0, "leg")
add("How many of these numbers are greater than 45: 41.2, 38.5, 47.9, 52.3, 36.8, 44.1, 49.6? The answer is an integer.", 3, 0, "leg")
# --- variantes piégées (un élément change le calcul)
add("A bakery recorded these daily receipts in euros: 412, 388, 505, 467. What is the total after a 10% commission is deducted? Round to 2 decimals.", 1772*.9, 2, "tw")
add("A bakery recorded these daily receipts in euros: 412, 388, 505, 467. What is the total, in cents? Give a whole number.", 177200, 0, "tw")
add("A bakery recorded these daily receipts in euros: 412, 388, 505, 467. What is the total of the two best days? Give a whole number.", 972, 0, "tw")
add("How many days are there from 3 January 2020 to 17 March 2020, weekends excluded? Give a whole number.", sum((D(2020,1,3)+dt.timedelta(i)).isoweekday()<=5 for i in range((D(2020,3,17)-D(2020,1,3)).days)), 0, "tw")
add("A lease starts on 1 June 2015 and ends on 31 May 2018. How many full months long is it? Give a whole number.", 35, 0, "tw")
add("What is the date 200 working days after 15 August 2023? Answer with a number of the form YYYYMMDD (for example 20240307 for March 7, 2024). Give a whole number.", 20240521, 0, "tw")
add("What is the base-10 logarithm of the square of 517? Round to 4 decimals.", 2*log10(517), 4, "tw")
add("What is the natural logarithm of 12.5 divided by the natural logarithm of 2? Report it with 4 decimals.", log(12.5)/log(2), 4, "tw")
add("Compute 9.2 raised to the power 3/2, then subtract 5. Round to 3 decimals.", 9.2**1.5-5, 3, "tw")
add("Compute the reciprocal of √7. Give the answer rounded to 3 decimal places.", 1/sqrt(7), 3, "tw")
add("A savings account starts at 3000 euros and earns 3% per year, interest reinvested. How much does it hold after 5 years if 200 euros are withdrawn at the end? Give the answer rounded to 2 decimal places.", 3000*1.03**5-200, 2, "tw")
add("A savings account starts at 3000 euros and earns 3% per year, interest reinvested. How much more does it hold after 5 years than after 4 years? Give the answer rounded to 2 decimal places.", 3000*1.03**5-3000*1.03**4, 2, "tw")
add("A town's library loans grew from 1200 to 1850 in 4 years. What constant monthly growth rate, in percent, gives the same result? Round your answer to 3 decimal places.", ((1850/1200)**(1/48)-1)*100, 3, "tw")
add("1500 euros are placed at 3.2% compound interest per year. What is the balance after 6 years, in thousands of euros? Round to 3 decimals.", 1500*1.032**6/1000, 3, "tw")
add("A van bought for 18,000 euros loses 12% of its value every year. What fraction of its initial value is it worth after 4 years? Give the answer rounded to 4 decimal places.", .88**4, 4, "tw")
add("An amount of 8000 euros earns 3% compound interest per year. After how many full years does it first reach at least triple its initial value? The answer is an integer.", next(n for n in range(999) if 1.03**n >= 3), 0, "tw")
add("How many ordered arrangements of 4 items can be made from 9 distinct items if the first item is fixed? Answer with an integer.", perm(8,3), 0, "tw")
add("What is the least common multiple of 84 and 126, minus their greatest common divisor? Give a whole number.", math.lcm(84,126)-gcd(84,126), 0, "tw")
add("In how many ways can a team of 4 be chosen from 10 people (order does not matter) if two given people refuse to work together? Give a whole number.", comb(10,4)-comb(8,2), 0, "tw")
add("What is the remainder of the division of 987654 by 37, squared? Give a whole number.", (987654 % 37)**2, 0, "tw")
add("An invoice of 480.00 euros includes VAT at 20%. What is the amount before VAT after a 5% discount on that amount? Report it with 2 decimals.", 380, 2, "tw")
add("A price rises by 10% and falls by 25%, one change after the other. What is the overall percentage change for a starting price of 80 euros, in euros (negative for a decrease)? Give the answer rounded to 2 decimal places.", 80*(1.1*.75-1), 2, "tw")
add("The price of a bike is 345.00 euros once a 15% increase is applied. Find the original price of two bikes. Report it with 2 decimals.", 600, 2, "tw")
add("The population of a town went from 15200 to 14100. What is the average percentage change per year over 5 years? Report it with 2 decimals.", ((14100/15200)**.2-1)*100, 2, "tw")
add("2% of cases have a leak in a pipe. A test detects it in 90% of the cases that have it, and wrongly flags 10% of the cases that do not. A case tests positive twice in independent tests. What is the probability, in percent, that it really has a leak in a pipe? Give the answer rounded to 2 decimal places.", .02*.81/(.02*.81+.98*.01)*100, 2, "tw")
add("A game pays 10 euros with probability 30%, 20 euros with probability 50% and 100 euros with probability 20%. What is the expected gain per game after a 5 euros entry ticket, in euros? Give the answer rounded to 2 decimal places.", 28, 2, "tw")
add("A game pays 10 euros with probability 30%, 20 euros with probability 50% and 100 euros with probability 20%. What is the standard deviation of the gain per game, in euros? Give the answer rounded to 2 decimal places.", sqrt(100*.3+400*.5+10000*.2-33**2), 2, "tw")
add("A machine produces a defective part with probability 0.2. Among 8 parts, what is the probability of at least 3 defective ones given that the first part is defective? Report it with 4 decimals.", sum(comb(7,k)*.2**k*.8**(7-k) for k in range(2,8)), 4, "tw")
add("3 fair six-sided dice are thrown. What is the probability that the faces add up to 10 and are all different? Round your answer to 4 decimal places.", sum(sum(r)==10 and len(set(r))==3 for r in it.product(range(1,7),repeat=3))/216, 4, "tw")
add(f"The waiting times of 7 patients were {s(B)} (minutes). What is the mean of the values other than the two extremes? Round to 2 decimals.", st.mean(sorted(B)[1:-1]), 2, "tw")
add(f"The waiting times of 7 patients were {s(B)} (minutes). What is the mean, expressed in hours? Round to 3 decimals.", st.mean(B)/60, 3, "tw")
add(f"The heights of 7 seedlings in a nursery were {s(B)} (cm). What is the median of the four tallest? Give the answer rounded to 2 decimal places.", st.median(sorted(B)[-4:]), 2, "tw")
add(f"The heights of 7 seedlings in a nursery were {s(B)} (cm). What is the gap between the mean and the median? Give the answer rounded to 2 decimal places.", st.mean(B)-st.median(B), 2, "tw")
add(f"A swimmer logged these lap times over 7 laps: {s(B)} (seconds). What is their population standard deviation (divide by n), as a percentage of the mean? Report it with 2 decimals.", st.pstdev(B)/st.mean(B)*100, 2, "tw")
add("A student has 14 in maths (coefficient 4), 11 in French (coefficient 3) and 16 in sport (coefficient 1). What is the weighted mean of the marks if the sport coefficient is doubled? Round to 2 decimals.", (56+33+32)/9, 2, "tw")
add("One pump fills a tank in 6 hours and a second pump fills it in 10 hours. A leak empties the full tank in 15 hours. With both pumps on and the leak open, how many hours do they take to fill three quarters of the tank? Round to 2 decimals.", .75/(1/6+1/10-1/15), 2, "tw")
add("Solve the system 3x + 4y = 50 and 2x + 1y = 20. What is the value of 2x − y? The answer is an integer.", 8, 0, "tw")
add("A company employs 12 people, each working 38 hours a week at 19.50 euros an hour. Over 8 weeks, each employee also receives a one-off bonus of 300 euros. What is the total paid out over the 8 weeks, per employee, in euros? Report it with 2 decimals.", 38*19.5*8+300, 2, "tw")
add("1 mile = 1.609 km. Convert 26.2 miles to kilometres, then add 5 km. Report it with 2 decimals.", 26.2*1.609+5, 2, "tw")
